def transform(grid):
    """For each 4-connected nonzero object, color centers of its full 3x3 patches
    with the object's embedded marker color.
    """
    h, w = len(grid), len(grid[0])
    labels = [[-1] * w for _ in range(h)]
    colors = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or labels[r][c] != -1:
                continue
            idx = len(colors)
            q = deque([(r, c)])
            labels[r][c] = idx
            mark = None
            while q:
                y, x = q.popleft()
                if grid[y][x] not in (0, 1):
                    mark = grid[y][x]
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and labels[ny][nx] == -1:
                        labels[ny][nx] = idx
                        q.append((ny, nx))
            colors.append(mark)

    out = [row[:] for row in grid]
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            idx = labels[r][c]
            if idx < 0 or colors[idx] is None:
                continue
            if all(labels[y][x] == idx for y in range(r - 1, r + 2) for x in range(c - 1, c + 2)):
                if grid[r][c] == 1:
                    out[r][c] = colors[idx]
    return out
